import xml.etree.ElementTree as ET

tree = ET.parse('/work/output/artifacts/skill-bpmn-simple-approval-bpmn/ExpenseApprovalBpmn/ExpenseApprovalBpmn.bpmn')
root = tree.getroot()

ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

errors = []

# 1. Root element check
tag = root.tag
if 'definitions' not in tag:
    errors.append(f"Root is not definitions: {tag}")
else:
    print("CHECK 1 PASS: root is definitions")

# 2. BPMNDiagram present
diagrams = root.findall('.//bpmndi:BPMNDiagram', ns)
if not diagrams:
    errors.append("No BPMNDiagram found")
else:
    print(f"CHECK 2 PASS: {len(diagrams)} BPMNDiagram(s) found")

# Collect all element IDs in the process
process = root.find('bpmn:process', ns)
all_ids = {}
for el in process.iter():
    eid = el.get('id')
    if eid:
        all_ids[eid] = el.tag

print(f"IDs in process: {list(all_ids.keys())}")

# Collect flow nodes and sequence flows
start_events = process.findall('.//bpmn:startEvent', ns)
end_events = process.findall('.//bpmn:endEvent', ns)
service_tasks = process.findall('.//bpmn:serviceTask', ns)
send_tasks = process.findall('.//bpmn:sendTask', ns)
script_tasks = process.findall('.//bpmn:scriptTask', ns)
gateways_xor = process.findall('.//bpmn:exclusiveGateway', ns)
seq_flows = process.findall('.//bpmn:sequenceFlow', ns)

print(f"\nFlow elements:")
print(f"  startEvents: {[e.get('id') for e in start_events]}")
print(f"  endEvents: {[e.get('id') for e in end_events]}")
print(f"  serviceTasks: {[e.get('id') for e in service_tasks]}")
print(f"  sendTasks: {[e.get('id') for e in send_tasks]}")
print(f"  scriptTasks: {[e.get('id') for e in script_tasks]}")
print(f"  exclusiveGateways: {[e.get('id') for e in gateways_xor]}")
print(f"  sequenceFlows: {[e.get('id') for e in seq_flows]}")

# 3. Resolve all sourceRef/targetRef
for f in seq_flows:
    src = f.get('sourceRef')
    tgt = f.get('targetRef')
    if src not in all_ids:
        errors.append(f"Flow {f.get('id')}: unresolved sourceRef={src}")
    if tgt not in all_ids:
        errors.append(f"Flow {f.get('id')}: unresolved targetRef={tgt}")

print("\nCHECK 3: sourceRef/targetRef resolution")
if not errors:
    print("  PASS: all refs resolved")

# 4. XOR gateways: non-default flows have conditions, exactly one default
for gw in gateways_xor:
    gwid = gw.get('id')
    default_flow = gw.get('default')
    outgoing_refs = [o.text for o in gw.findall('bpmn:outgoing', ns)]
    print(f"\n  Gateway {gwid}: outgoing={outgoing_refs}, default={default_flow}")
    non_default = [r for r in outgoing_refs if r != default_flow]
    for fid in non_default:
        flow_el = process.find(f'.//bpmn:sequenceFlow[@id="{fid}"]', ns)
        if flow_el is None:
            errors.append(f"Gateway {gwid}: outgoing flow {fid} not found")
            continue
        cond = flow_el.find('bpmn:conditionExpression', ns)
        if cond is None:
            errors.append(f"Gateway {gwid}: non-default flow {fid} has no conditionExpression")
        else:
            print(f"    Flow {fid} condition: {cond.text.strip()}")
    if not default_flow:
        errors.append(f"Gateway {gwid}: no default flow set")
    else:
        print(f"    default={default_flow} PASS")

# 5. No activity/event with more than one incoming flow
for el in list(start_events) + list(end_events) + list(service_tasks) + list(send_tasks) + list(script_tasks):
    incomings = [i.text for i in el.findall('bpmn:incoming', ns)]
    if len(incomings) > 1:
        errors.append(f"FAKE_JOIN: element {el.get('id')} has {len(incomings)} incoming flows")

print("\nCHECK 5: No fake joins")
if not errors:
    print("  PASS")

# 6. BPMNShape per node, BPMNEdge per flow
plane = root.find('.//bpmndi:BPMNPlane', ns)
shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', ns)}
edges = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', ns)}

flow_nodes = (list(start_events) + list(end_events) + list(service_tasks) +
              list(send_tasks) + list(script_tasks) + list(gateways_xor))
for el in flow_nodes:
    if el.get('id') not in shapes:
        errors.append(f"No BPMNShape for {el.get('id')}")
for f in seq_flows:
    if f.get('id') not in edges:
        errors.append(f"No BPMNEdge for {f.get('id')}")

print("\nCHECK 6: BPMNShape/BPMNEdge coverage")
if not [e for e in errors if 'BPMNShape' in e or 'BPMNEdge' in e]:
    print(f"  PASS: {len(shapes)} shapes, {len(edges)} edges")

# 7. vars. references resolve
import re
bpmn_str = open('/work/output/artifacts/skill-bpmn-simple-approval-bpmn/ExpenseApprovalBpmn/ExpenseApprovalBpmn.bpmn').read()
var_refs = set(re.findall(r'vars\.(\w+)', bpmn_str))
var_ids = set()
for v in process.findall('.//uipath:inputOutput', ns):
    var_ids.add(v.get('id'))
print(f"\nCHECK 7: vars.* references: {var_refs}")
print(f"  Declared var IDs: {var_ids}")
for ref in var_refs:
    if ref not in var_ids:
        errors.append(f"vars.{ref} has no declared variable")
if all(r in var_ids for r in var_refs):
    print("  PASS: all vars.* resolved")

# 8. scriptFormat on scriptTask
for st in script_tasks:
    sf = st.get('scriptFormat')
    if sf != 'JavaScript':
        errors.append(f"ScriptTask {st.get('id')}: scriptFormat={sf}, expected JavaScript")
    else:
        print(f"\nCHECK 8 PASS: scriptTask {st.get('id')} scriptFormat=JavaScript")

# Final report
print("\n--- VALIDATION RESULT ---")
if not errors:
    print("VALID: all checks passed")
else:
    print("ERRORS:")
    for e in errors:
        print(f"  ERROR: {e}")
EOF
